    let b = f.as_bytes(); let mut o = String::new(); let mut i = 0;
    while i < b.len() {
        let c = b[i];
        if c == b'"' { let st = i; i += 1; while i < b.len() { if b[i] == b'"' { if i + 1 < b.len() && b[i + 1] == b'"' { i += 2; continue; } i += 1; break; } i += 1; } o.push_str(&f[st..i]); continue; }
        if c.is_ascii_alphabetic() || c == b'$' {
