                let nc = if ca { col } else { col + dc }; let nr = if ra { row } else { row + dr };
                o.push_str(&format!("{}{}{}{}", if ca { "$" } else { "" }, n_to_col(nc as u32), if ra { "$" } else { "" }, nr));
