cd /workspace/submission && python3 - <<'E'
p='src/main.rs'; s=open(p).read()
a=s.index('    fn bsearch(&mut self')
b=s.index('fn rank_t(')
new='''    fn bsearch(&mut self, len: u32, key: &V, get: &dyn Fn(&mut Eng, u32) -> V) -> Option<u32> { self.lscan(len, key, get, false) }
    fn bsearch_desc(&mut self, len: u32, key: &V, get: &dyn Fn(&mut Eng, u32) -> V) -> Option<u32> { self.lscan(len, key, get, true) }
    fn lscan(&mut self, len: u32, key: &V, get: &dyn Fn(&mut Eng, u32) -> V, desc: bool) -> Option<u32> {
        use std::cmp::Ordering::*;
        let mut res = None;
        for i in 0..len {
            let v = get(self, i);
            if matches!(v, V::Empty) || rank_t(&v) != rank_t(key) { continue; }
            match (cmp_vals(&v, key), desc) {
                (Equal, _) => return Some(i),
                (Less, false) | (Greater, true) => res = Some(i),
                _ => break,
            }
        }
        res
    }
}
'''
s=s[:a]+new+s[b:]
