use std::alloc::{GlobalAlloc, Layout, System};
use std::cell::Cell;

pub struct Bump;
const BIG: usize = 32 * 1024;
const CHUNK: usize = 4 << 20;
thread_local! { static CUR: Cell<(usize, usize)> = const { Cell::new((0, 0)) }; }

unsafe impl GlobalAlloc for Bump {
    #[inline]
    unsafe fn alloc(&self, l: Layout) -> *mut u8 {
        if l.size() > BIG || l.align() > 4096 { return System.alloc(l); }
        match CUR.try_with(|c| {
            let (p, end) = c.get();
            let a = l.align();
            let q = (p + a - 1) & !(a - 1);
            if p != 0 && q + l.size() <= end { c.set((q + l.size(), end)); return q as *mut u8; }
            let base = System.alloc(Layout::from_size_align_unchecked(CHUNK, 4096)) as usize;
            if base == 0 { return std::ptr::null_mut(); }
            let q = (base + a - 1) & !(a - 1);
            c.set((q + l.size(), base + CHUNK));
            q as *mut u8
        }) { Ok(p) => p, Err(_) => System.alloc(l) }
    }
    #[inline]
    unsafe fn dealloc(&self, p: *mut u8, l: Layout) {
        if l.size() > BIG || l.align() > 4096 { System.dealloc(p, l); }
    }
}
