import openpyxl,random,glob,os,sys,re
seed=int(sys.argv[1]); random.seed(seed)
os.makedirs(f'/tmp/fz/b{seed}',exist_ok=True)
def mut(f):
    parts=re.split(r'("(?:[^"]|"")*")',f)
    out=[]
    for p in parts:
        if p.startswith('"'):
            if random.random()<0.2: p=random.choice(['""','"a"','"West"','"<5"','">=100"','"F*"','"0"','"x y"','" 3 "'])
            out.append(p); continue
        def r(m):
            if random.random()<0.35: return random.choice(['0','1','2','3','-1','5','10','0.5','-2.5','100','1.5'])
            return m.group(0)
        out.append(re.sub(r'(?<![A-Za-z$0-9.:!])\d+(\.\d+)?(?![0-9.:]|\s*!)',r,p))
